#!/usr/bin/env python3
"""Extract the published C++20 fence and test independent physical bag allocations."""
from pathlib import Path
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile

HARNESS = '\n#include <chrono>\n#include <climits>\n#include <cstdlib>\n#include <functional>\n#include <iostream>\n#include <random>\n#include <set>\n#include <string>\nusing I = std::int64_t;\nusing U = std::uint64_t;\nusing Wide = unsigned __int128;\nstd::uint64_t checks=0, allocations=0, exhaustive_cases=0, checksum=0;\nstd::size_t max_states=0;\nvoid require(bool condition,const char* message) {\n    ++checks;\n    if(!condition){std::cerr<<"FAIL: "<<message<<\'\\n\';std::exit(1);}\n}\nU total_of(const std::vector<I>& amounts) {\n    Wide total=0;\n    for(std::size_t i=0;i<amounts.size();++i)total+=Wide(amounts[i])<<i;\n    require(total<=Wide(INT64_MAX),"test input has valid weighted supply");\n    return static_cast<U>(total);\n}\nequal_bags_detail::Counter make_counter(I bags,const std::vector<I>& amounts) {\n    equal_bags_detail::Counter c;Wide total=0;\n    for(std::size_t i=0;i<63;++i){if(i<amounts.size())total+=Wide(amounts[i])<<i;c.cap[i]=static_cast<U>(total/Wide(bags))+1;}\n    return c;\n}\nU checked(I bags,const std::vector<I>& amounts) {\n    const U total=total_of(amounts);\n    const U answer=count_equal_bag_tastiness(bags,amounts);\n    auto counter=make_counter(bags,amounts);\n    require(counter.count(total/static_cast<U>(bags)+1)==answer,"actual memoized counter matches public API");\n    const std::size_t bits=std::bit_width(total);\n    require(counter.memo.size()<=bits*(bits+1)/2,"proved triangular state bound");\n    max_states=std::max(max_states,counter.memo.size());\n    require(answer>=1 && answer<=total/static_cast<U>(bags)+1,"output count and zero-bag value bounds");\n    checksum=checksum*1000003+answer;\n    return answer;\n}\n// Independent oracle: assign each physical biscuit to one of the x labeled\n// bags or leave it unused. At a leaf, count its taste only if all sums agree.\n// Neither prefix inequalities nor the counting recurrence occur in this oracle.\nstd::set<U> direct_values(int bags,const std::vector<I>& amounts) {\n    std::vector<U> pieces;\n    for(std::size_t bit=0;bit<amounts.size();++bit)\n        for(I count=0;count<amounts[bit];++count)pieces.push_back(U{1}<<bit);\n    std::vector<U> sums(bags,0);std::set<U> tastes;\n    std::function<void(std::size_t)> assign=[&](std::size_t pos){\n        if(pos==pieces.size()){\n            ++allocations;\n            if(std::all_of(sums.begin(),sums.end(),[&](U value){return value==sums[0];}))tastes.insert(sums[0]);\n            return;\n        }\n        assign(pos+1); // Unused biscuit.\n        for(U& sum:sums){sum+=pieces[pos];assign(pos+1);sum-=pieces[pos];}\n    };\n    assign(0);return tastes;\n}\nbool prefix_test(I bags,const std::vector<I>& amounts,U taste) {\n    Wide prefix=0;\n    for(std::size_t bit=0;bit<63;++bit){\n        if(bit<amounts.size())prefix+=Wide(amounts[bit])<<bit;\n        const U residue=taste&((U{1}<<(bit+1))-1);\n        if(Wide(bags)*residue>prefix)return false;\n    }\n    return true;\n}\nvoid compare(int bags,const std::vector<I>& amounts,bool every_bound) {\n    const auto tastes=direct_values(bags,amounts);\n    require(checked(bags,amounts)==tastes.size(),"count distinct tastes from all physical bag allocations");\n    if(every_bound){\n        const U total=total_of(amounts);\n        for(U t=0;t<=total+1;++t)\n            require(prefix_test(bags,amounts,t)==tastes.contains(t),"necessary and sufficient prefix theorem versus direct bags");\n        for(U upper=0;upper<=total+2;++upper){\n            auto c=make_counter(bags,amounts);\n            const auto expected=static_cast<U>(std::distance(tastes.begin(),tastes.lower_bound(upper)));\n            require(c.count(upper)==expected,"every exclusive bound versus direct taste set");\n        }\n    }\n}\nvoid exhaustive(){\n    for(int types=0;types<=5;++types){\n        std::vector<I> amounts(types,0);\n        std::function<void(int)> generate=[&](int pos){\n            if(pos==types){for(int bags=1;bags<=4;++bags){++exhaustive_cases;compare(bags,amounts,true);}return;}\n            for(I amount=0;amount<=2;++amount){amounts[pos]=amount;generate(pos+1);}\n        };\n        generate(0);\n    }\n    require(exhaustive_cases==1456,"all supplies 0..2, types 0..5 and all bags 1..4");\n}\nvoid boundary(){\n    require(checked(3,{5,2,1})==5,"official example 1");\n    require(checked(2,{2,1,2})==6,"official example 2");\n    require(checked(INT64_MAX,{})==1,"empty inventory and maximum bags");\n    require(checked(1,std::vector<I>(63,0))==1,"all zero types");\n    require(checked(1,{INT64_MAX})==(U{1}<<63),"2^63 distinct tastes, including zero");\n    require(checked(2,{INT64_MAX})==(U{1}<<62),"large odd supply divided among two bags");\n    require(checked(INT64_MAX,{INT64_MAX})==2,"one biscuit for each of maximum bags");\n    std::vector<I> binary(63,1);\n    require(checked(1,binary)==(U{1}<<63),"all binary subsets through INT64_MAX");\n    require(checked(2,binary)==1,"huge total cannot repair the lowest insufficient supply");\n    require(checked(INT64_MAX,binary)==1,"maximum bags need physical biscuits, not just aggregate taste");\n    std::vector<I> twice(62,2);\n    require(checked(2,twice)==(U{1}<<62),"two complete binary sets");\n    require(checked(1,twice)==U(INT64_MAX),"all values through INT64_MAX-1");\n    for(int bit=0;bit<=62;++bit){\n        const I max_amount=INT64_MAX>>bit;\n        for(I amount:{I{0},I{1},max_amount})for(I bags:{I{1},I{2},I{3},I{1000000000},I{INT64_MAX}}){\n            std::vector<I> supply(bit+1,0);supply[bit]=amount;\n            require(checked(bags,supply)==U(amount/bags)+1,"single-denomination closed form at every bit");\n        }\n    }\n    std::mt19937_64 rng(20200919);\n    for(int trial=0;trial<128;++trial){\n        std::vector<I> supply(63,0);int pieces=1+int(rng()%8);\n        while(pieces--){int bit=int(rng()%60);if(supply[bit]<2)++supply[bit];}\n        compare(1+int(rng()%4),supply,false);\n    }\n    // Multiplying every weight by a power of two bijects the taste set.\n    for(int trial=0;trial<2000;++trial){\n        int types=1+int(rng()%40),shift=int(rng()%21);\n        std::vector<I> supply(types);for(I& amount:supply)amount=I(rng()%4);\n        I bags=1+I(rng()%1000000);if(trial%3==0)bags=1+I(rng()%8);\n        const U expected=checked(bags,supply);\n        std::vector<I> shifted(shift,0);shifted.insert(shifted.end(),supply.begin(),supply.end());\n        require(checked(bags,shifted)==expected,"common power-of-two weight scaling");\n        shifted.resize(63,0);\n        require(checked(bags,shifted)==expected,"trailing zero types do not change the answer");\n    }\n    for(int trial=0;trial<3000;++trial){\n        std::vector<I> supply(63,0);U total=0;\n        for(int bit=0;bit<63;++bit){U allowed=(U(INT64_MAX)-total)>>bit;U amount=std::min(allowed,rng()%8);supply[bit]=I(amount);total+=amount<<bit;}\n        I bags=trial%2?1+I(rng()%1000000000000ULL):1+I(rng()%16);\n        (void)checked(bags,supply);\n    }\n}\n// Exactly the original maximum q, with K=60 and independently known answers.\nvoid original_limit_batch(){\n    constexpr I bound=1000000000000000000LL;\n    for(int scenario=0;scenario<1000;++scenario){\n        std::vector<I> supply(60,0);I bags;U expected;\n        switch(scenario%4){\n        case 0:supply[0]=bound;bags=1;expected=U(bound)+1;break;\n        case 1:supply[0]=bound;bags=bound;expected=2;break;\n        case 2:supply[59]=1;supply[0]=bound-(I{1}<<59);bags=1;expected=2*(U(supply[0])+1);break;\n        default:supply[59]=1;bags=bound;expected=1;\n        }\n        const U answer=checked(bags,supply);\n        require(answer==expected,"original K=60, x/T=1e18 and q=1000 independent closed forms");\n        require(answer<=U(INT64_MAX),"original answer safely narrows to the judge int64 return type");\n    }\n}\nvoid rejects(I bags,const std::vector<I>& amounts){\n    bool threw=false;try{(void)count_equal_bag_tastiness(bags,amounts);}catch(const std::invalid_argument&){threw=true;}\n    require(threw,"invalid input rejected before arithmetic");\n}\nint main(){\n    const auto start=std::chrono::steady_clock::now();exhaustive();boundary();original_limit_batch();\n    rejects(0,{});rejects(-1,{});rejects(INT64_MIN,{});rejects(0,{1});\n    rejects(1,{-1});rejects(INT64_MAX,{0,0,-1});rejects(1,{INT64_MIN});\n    rejects(1,std::vector<I>(64,0));rejects(1,{INT64_MAX,1});rejects(1,{0,INT64_MAX});\n    std::vector<I> too_high(63,0);too_high[62]=2;rejects(1,too_high);\n    std::cout<<"{\\"checks\\":"<<checks<<",\\"exhaustiveCases\\":"<<exhaustive_cases\n             <<",\\"originalLimitScenarios\\":1000,\\"physicalAllocations\\":"<<allocations<<",\\"maxMemoStatesObserved\\":"<<max_states\n             <<",\\"provedStateBound\\":2016,\\"checksum\\":\\""<<checksum<<"\\",\\"seconds\\":"\n             <<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<"}\\n";\n}\n'

args = [arg for arg in sys.argv[1:] if arg != '--sanitize']
article = Path(args[0]) if args else Path(__file__).resolve().parents[1] / 'src/content/docs/techniques/bounded-power-two-equal-bag-prefix-cap-memoization.mdx'
blocks = re.findall(r'^```cpp\s*\n(.*?)^```\s*$', article.read_text(), re.M | re.S)
if len(blocks) != 1:
    raise RuntimeError('expected exactly one complete visible C++ fence')
with tempfile.TemporaryDirectory(prefix='flowchartcp-biscuits-') as directory:
    source = Path(directory)/'check.cpp'
    binary = Path(directory)/'check'
    source.write_text(blocks[0]+'\n'+HARNESS)
    flags = ['-std=c++20','-O2','-Wall','-Wextra','-Werror']
    environment = os.environ.copy()
    if '--sanitize' in sys.argv:
        flags += ['-O1','-g','-fsanitize=address,undefined','-fno-omit-frame-pointer']
        environment['ASAN_OPTIONS'] = 'detect_leaks=0'
    compiler = environment.get('CXX') or shutil.which('g++') or shutil.which('clang++') or 'c++'
    subprocess.run([compiler,*flags,str(source),'-o',str(binary)],check=True,timeout=120)
    timer = Path('/usr/bin/time')
    command = [str(timer),'-f','peak_rss_kib=%M',str(binary)] if timer.exists() and sys.platform.startswith('linux') else [str(binary)]
    run = subprocess.run(command,check=True,text=True,capture_output=True,env=environment,timeout=180)
    report = json.loads(run.stdout)
    match = re.search(r'^peak_rss_kib=(\d+)$',run.stderr,re.M)
    if match:
        report['peakRSSKiB'] = int(match[1])
    report.update(article=str(article),sanitized='--sanitize' in sys.argv)
    print(json.dumps(report,ensure_ascii=False,indent=2))
